python3 -I - <<'PYEOF'
import json,re,importlib.util,collections,statistics as st,ast
from fractions import Fraction
W='/user/user1/autorlbench-runs/20261122021645-64623-785a/workspace'
spec=importlib.util.spec_from_file_location('cr',W+'/reward/countdown_reward.py')
cr=importlib.util.module_from_spec(spec);spec.loader.exec_module(cr)
R=W+'/results/grpo_countdown/'
def load(p): return [json.loads(l) for l in open(R+p)]
def cat(o,g):
    m=cr.ANSWER_RE.findall(o)
    if not m: return 'no_tag'
    e=m[-1].strip()
    if '=' in e: e=e.split('=')[0].strip()
    if not e or len(e)>256 or not cr.ALLOWED_CHARS_RE.fullmatch(e): return 'bad_chars'
    try:
        u=[];v=cr._eval_ast(ast.parse(e,mode='eval'),u)
    except Exception: return 'parse_err'
    if sorted(u)!=sorted(int(x) for x in g['numbers']): return 'wrong_nums'
    return 'correct' if v==Fraction(int(g['target'])) else 'wrong_value'
def solv(nums,t):
    def rec(xs):
        if len(xs)==1: return xs[0]==t
        for i in range(len(xs)):
            for j in range(len(xs)):
                if i==j: continue
                a,b=xs[i],xs[j]
                rest=[xs[k] for k in range(len(xs)) if k!=i and k!=j]
                cands=[a+b,a-b,a*b]
                if b!=0: cands.append(a/b)
                for c in cands:
                    if rec(rest+[c]): return True
        return False
    return rec([Fraction(x) for x in nums])
for f in ['val_generations/0.jsonl','val_generations/45.jsonl','rollouts/1.jsonl','rollouts/45.jsonl']:
    D=load(f);C=collections.Counter();mism=0;L=collections.defaultdict(list)
    for d in D:
        g=json.loads(d['gts']);c=cat(d['output'],g);C[c]+=1;L[c].append(len(d['output']))
        if (cr.score_countdown(d['output'],g)==1.0)!=(float(d['score'])==1.0): mism+=1
    print(f,len(D),dict(C),'mismatch_vs_logged',mism,{k:round(st.mean(v)) for k,v in L.items()},'mean_chars',round(st.mean(len(d['output']) for d in D)))
for f in ['val_generations/0.jsonl','val_generations/45.jsonl']:
    D=load(f);T=collections.defaultdict(lambda:[0,0])
    for d in D:
        n=len(json.loads(d['gts'])['numbers']);T[n][0]+=float(d['acc']);T[n][1]+=1
    print('acc_by_n',f,{n:(v[0],v[1]) for n,v in T.items()})
for f in ['rollouts/1.jsonl','rollouts/45.jsonl']:
    D=load(f);G=collections.defaultdict(list)
    for d in D: G[d['input']].append(float(d['score']))
    print(f,'groups',len(G),'groups_with_any_success',sum(1 for v in G.values() if max(v)>0),'groups_all_success',sum(1 for v in G.values() if min(v)>0))
D=load('rollouts/45.jsonl')
for d in [d for d in D if len(d['output'])>1200][:2]: print('LONG',len(d['output']),repr(d['output'][:400]),'...',repr(d['output'][-200:]))
for d in [d for d in D if float(d['score'])>0][:2]: print('OK',repr(d['output'][:400]))
for d in [d for d in D if 200<len(d['output'])<=1200 and float(d['score'])==0][:2]: print('MID',repr(d['output'][:500]))
D=load('val_generations/0.jsonl')[:300];S=collections.Counter()
for d in D:
    g=json.loads(d['gts']);S[(len(g['numbers']),solv(g['numbers'],g['target']))]+=1
print('solvable (n_numbers, solvable):',dict(S))
PYEOF

